import{_ as o,a as e,b as a}from"./chunks/zmp-cal-3.BgHsVRDR.js";import{_ as i,o as n,c as r,a5 as s}from"./chunks/framework.CcrBcQWS.js";const f=JSON.parse('{"title":"4. ZMP Calibration","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"guides/add-on/zmp-calibration.md","filePath":"guides/add-on/zmp-calibration.md","lastUpdated":1787021357000}'),l={name:"guides/add-on/zmp-calibration.md"};function d(c,t,h,g,p,u){return n(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="_4-zmp-calibration" tabindex="-1">4. ZMP Calibration <a class="header-anchor" href="#_4-zmp-calibration" aria-label="Permalink to &quot;4. ZMP Calibration&quot;">​</a></h1><p><strong>Goal:</strong> Re-center the robot&#39;s Zero Moment Point so it stays balanced while standing and walking under the <strong>new add-on weight</strong>.</p><p><strong>Prerequisites:</strong> Step 3 <a href="/RBQ/nightly/guides/add-on/payload-setting.html">Payload Setting</a> is complete — mass and X/Y/Z offset are registered in the robot.</p><h2 id="what-zmp-calibration-does" tabindex="-1">What ZMP Calibration Does <a class="header-anchor" href="#what-zmp-calibration-does" aria-label="Permalink to &quot;What ZMP Calibration Does&quot;">​</a></h2><p>ZMP (Zero Moment Point) calibration aligns the center of ground reaction force while the robot is standing, so the robot can maintain balance during walking. Whenever you change payload, the center of mass shifts — this step compensates for it.</p><h2 id="before-you-start" tabindex="-1">Before You Start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before You Start&quot;">​</a></h2><ul><li>Place the robot on a <strong>flat, solid surface</strong>.</li><li>Make sure <strong>no objects or people are touching the robot</strong>.</li><li>RBQGUI is connected to the robot and the new payload is registered.</li></ul><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure&quot;">​</a></h2><ol><li>Launch <strong>RBQGUI</strong> and connect to the robot.</li><li>Set the robot to <strong>Stance</strong> (standing) mode.</li><li><strong>Press and hold</strong> the <strong>Sit</strong> button.</li></ol><figure style="text-align:center;"><img src="'+o+'" alt="Sit button" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 3 — press and hold Sit</figcaption></figure><ol start="4"><li>In the menu that appears, select <strong>ZMP CALIBRATE</strong>.</li></ol><figure style="text-align:center;"><img src="'+e+'" alt="ZMP CALIBRATE selection (Recovery menu)" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 4 — ZMP CALIBRATE</figcaption></figure><ol start="5"><li>When the button turns <strong>orange</strong>, calibration is in progress.</li><li><strong>Do not touch the robot</strong> until calibration finishes.</li></ol><figure style="text-align:center;"><img src="'+a+'" alt="Calibration in progress (ZMP Init)" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">Step 5 — calibration in progress</figcaption></figure><ol start="7"><li>When the button returns to <strong>white</strong> and the display shows <strong>Gait: Stance</strong>, calibration is complete.</li><li>Move the robot (Stance → Walk) and verify it walks normally with the new add-on.</li></ol><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Do not place objects on the robot or push the robot during calibration. If calibration fails, repeat the procedure.</p></div></div><h2 id="done" tabindex="-1">Done <a class="header-anchor" href="#done" aria-label="Permalink to &quot;Done&quot;">​</a></h2><p>Your add-on is mounted, registered, and the robot is calibrated for the new load. You can now command motions normally — return to <strong><a href="/RBQ/nightly/guides/common/basic-motion-command.html">Basic Motion Command</a></strong> to drive the robot.</p>',18)])])}const _=i(l,[["render",d]]);export{f as __pageData,_ as default};
